const URL_API_UPLOAD = process.env.NODE_ENV === 'production' 
                                            ? '/api/upload/' 
                                            : `http://localhost:${process.env.REACT_APP_PORT_SRV_DEV}/api/upload/`;

export function subirImagen(data, progress){
    return new Promise((resolve, reject) => {
        const xhr = new XMLHttpRequest();
        xhr.open('post', URL_API_UPLOAD);

        xhr.addEventListener('load', ()=>{

            if(xhr.status === 200){
                const rta = JSON.parse(xhr.response);
                console.log(rta);

                const urlFotoSubida = rta.urlFoto;

                if(urlFotoSubida){
                    resolve(urlFotoSubida);
                }else{
                    console.error('Respuesta inesperada:', rta);
                    reject(new Error('Respuesta inesperada del upload'));
                }
            } else {
                console.error('Error upload:', xhr.status, xhr.responseText);
                reject(new Error('Error al subir la imagen'));
            }
        });

        xhr.addEventListener('error', () => {
            console.error('Error de red al subir la imagen');
            reject(new Error('Error de red al subir la imagen'));
        });

        xhr.upload.addEventListener('progress', e => {
            if(e.lengthComputable && progress){
                const porcentaje = Math.round((e.loaded * 100) / e.total);
                console.warn(porcentaje,'%');
                progress(porcentaje);
            }
        });

        xhr.send(data);
    });
}

export function enviarFormDataAjax(data, progress, urlFoto, onError){

    subirImagen(data, progress)
        .then(urlFoto)
        .catch(() => {
            if (onError) onError();
        });

}
