import './Tabla.css'


export const Tabla = props => {

    const { carrito, borrarId, incrementarId, decrementarId } = props
    const formatearImporte = valor => Number(valor).toLocaleString('es-AR', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
    });

    return (
        <div className="Tabla">

            <div className="table-responsive">
                <table className="table table-dark">
                    <thead>
                        <tr>
                            <th>nombre</th>
                            <th>marca</th>
                            <th>foto</th>
                            <th>precio</th>
                            <th>cantidad</th>
                            <th>subtotal</th>
                            <th>acciones</th>
                        </tr>
                    </thead>
                    <tbody>
                        {
                            carrito.map((producto, index) =>
                                <tr key={index}>
                                    <td>{producto.nombre}</td>
                                    <td>{producto.marca}</td>
                                    <td><img width="100px" src={producto.foto} alt={"foto de " + producto.nombre} /></td>
                                    <td>${formatearImporte(producto.precio)}</td>
                                    <td>
                                        {producto.cantidad}
                                        <button className='btn btn-info ml-2' onClick={ () => decrementarId(producto.id)}>-</button>
                                        <button className='btn btn-info ml-2' onClick={ () => incrementarId(producto.id)}>+</button>
                                    </td>
                                    <td>
                                        ${formatearImporte(producto.precio * producto.cantidad)}
                                    </td>
                                    <td>
                                        <button className='btn btn-danger' onClick={ () => borrarId(producto.id) }>Borrar</button>
                                    </td>
                                </tr>
                            )
                        }
                        <tr>
                            <td></td>
                            <td></td>
                            <td></td>
                            <td></td>
                            <td><h4>Total</h4></td>
                            <td><h4>${formatearImporte(carrito.reduce(( acc, p ) => acc + ( p.precio * p.cantidad ) , 0 ))}</h4></td>
                            <td></td>
                        </tr>
                    </tbody>
                </table>
            </div>
        </div>
    )
}
