import './Index.css';
import { Tabla } from './Tabla';
import { useLocalStorage } from '../../HOOKS/useLocalStorage';
import { enviarCarrito, getPreference } from '../../Servicios/ServiciosCarrito';

// Importa el SDK de Mercado Pago
import { Wallet } from '@mercadopago/sdk-react';
import './pago'; 

export default function Index() {


    const [carrito, setCarrito] = useLocalStorage('carrito', []);
    
    function BorrarAll() {
        setCarrito([]);
    }
    function borrarId(id) {
        const carritoClon = [...carrito];
        const index = carritoClon.findIndex(p => p.id === id);
        carritoClon.splice(index, 1);

        setCarrito(carritoClon);

    }
    function decrementarId(id) {
        const carritoClon = [...carrito]
        const producto = carritoClon.find(p => p.id === id)
        if (producto.cantidad > 1) {
            producto.cantidad--
            setCarrito(carritoClon)
        }
    }
    function incrementarId(id) {
        const carritoClon = [...carrito]
        const producto = carritoClon.find(p => p.id === id)
        if (producto.cantidad < producto.stock) {
            producto.cantidad++
            setCarrito(carritoClon)
            console.log(carrito)
        }
    }

    async function pedir(){
        
        const carritoEnviado = await enviarCarrito({ pedido: carrito });
        console.log(carritoEnviado);
        setCarrito([]);

    }

    //Modifico wallet de mp

    const customization = {
        texts: {
            action: 'buy',
            valueProp: 'security_details'
        }
    }

    const onReady = ()=>{
        console.log('Wallet is ready');
    }

    const onError = (error)=>{
        console.log(error)
    }

    const onSubmit = async (data) => {
        console.log('Submiting payment with data:', data);

        try {
            const response = await getPreference(carrito);
            return response.data.preferenceId;
        } catch (error) {
            console.error('Error creating preference:', error);
            throw error;
        }
    };


    return (
        <div className="Carrito">
            <div className="jumbotron">
                <h1>Carrito de compras</h1>
                <hr />

                <div className="carrito">



                    {carrito.length === 0 && <h3 className='alert alert-danger'>No se encontraron pedidos</h3>}
                    {carrito.length > 0 &&
                        <>
                            <button className="carrito_borrar" onClick={BorrarAll}>Borrar</button>
                            <Tabla
                                carrito={carrito}
                                borrarId={borrarId}
                                incrementarId={incrementarId}
                                decrementarId={decrementarId}
                            />
                            <button className="carrito_pedir" onClick={pedir}>Pedir</button>
                            <div id='wallet_container'>
                                <Wallet 
                                    customization={customization}
                                    onReady={onReady}
                                    onError={onError}
                                    onSubmit={onSubmit}
                                />
                            </div>
                        </>
                    }
                </div>
            </div>
        </div>
    )
}