import axios from "axios";

const URL_API_PRODUCTOS = process.env.NODE_ENV === 'production' 
                        ? '/api/productos/' 
                        : `http://localhost:${process.env.REACT_APP_PORT_SRV_DEV}/api/productos/`;

const eliminarPropiedad = (obj, prop) => {
    const objClon = {...obj};
    delete objClon[prop];

    return objClon;
}

const proxyProducto = producto => {
    const handler = {
        get: function(target, prop, receiver){

            if(prop === 'id'){
                const id = target._id
                target.id = id
                return id
            }
            return Reflect.get (...arguments)
        }

    }

    return new Proxy(producto, handler)
}

export async function obtenerProductos(){
    
    try{
        
        const {data:productoLeido} = await axios.get(URL_API_PRODUCTOS);
        const productosLeidoProxy = productoLeido.map(producto => proxyProducto(producto));
        return productosLeidoProxy;

    }catch(error){

        console.log("ERROR GET AXIOS: ", error.message);
        return [];

    }    
}

export async function guardarProducto(producto){
    
    try{
        
        const {data: saveData} = await axios.post(URL_API_PRODUCTOS, producto);
        return proxyProducto(saveData);

    }catch(error){

        console.log("ERROR POST AXIOS: ", error.message);
        return [];

    }  
}

export async function actualizarProducto(id, producto){

    try{
        const productoSinIds = eliminarPropiedad(eliminarPropiedad(producto, '_id'), 'id');

        const { data:productoActualizado } = await axios.put(URL_API_PRODUCTOS+id, productoSinIds)
        console.log(productoActualizado);
        return proxyProducto(productoActualizado);

    }catch(error){

        console.log('ERROR PUT AXIOS: ', error.message);
        return;

    }


}

export async function borrarProducto(id){
    try{
        
        const {data: deletedProduct} = await axios.delete(URL_API_PRODUCTOS+ id);
        return proxyProducto(deletedProduct);

    }catch(error){

        console.log("ERROR DELETE AXIOS: ", error.message);
        return [];

    }  
}
