import './Ingreso.css';
import { ObtenerFoto } from './ObtenerFoto';

export default function Ingreso(props){
    
    const {nombre, precio, stock, detalles, foto, marca, categoria, envio} = props.producto;
    const {onChange, onSubmit, editarId, formInvalid, enviarArchivoFoto, borrarArchivoFoto, archivoPendiente, subiendoFoto} = props;

    return(

        <div className="Ingreso">
            <form onSubmit={ onSubmit }> 
                {/*--------Nombre---------*/}
                <div className="form-group">

                    <label htmlFor="nombre">Nombre</label>
                    <input type="text" id="nombre" className="form-control" value={ nombre } onChange={ onChange }/>
                </div>

                {/*--------Precio---------*/}
                <div className="form-group">

                    <label htmlFor="precio">Precio</label>
                    <input type="number" id="precio" className="form-control" value={ precio } onChange={ onChange } step="0.01" min="0.01"/>
                </div>

                {/*--------Stock---------*/}
                <div className="form-group">

                    <label htmlFor="stock">Stock</label>
                    <input type="number" id="stock" className="form-control" value={ stock } onChange={ onChange }/>
                </div>
                
                {/*--------Marca---------*/}
                <div className="form-group">

                    <label htmlFor="marca">Marca</label>
                    <input type="text" id="marca" className="form-control" value={ marca } onChange={ onChange }/>
                </div>
                
                {/*--------Categoria---------*/}
                <div className="form-group">

                    <label htmlFor="categoria">Categoria</label>
                    <input type="text" id="categoria" className="form-control" value={ categoria } onChange={ onChange }/>
                </div>
                
                {/*--------Detalles---------*/}
                <div className="form-group">

                    <label htmlFor="detalles">Detalles</label>
                    <input type="text" id="detalles" className="form-control" value={ detalles } onChange={ onChange }/>
                </div>
                
                {/*--------Zona de obtencion de la foto del producto---------*/}
                <ObtenerFoto
                    foto={foto}
                    archivoPendiente={archivoPendiente}
                    enviarArchivoFoto={enviarArchivoFoto}
                    borrarArchivoFoto={borrarArchivoFoto}
                    subiendo={subiendoFoto}
                />

                {/*--------Envio---------*/}
                <div className="form-group form-check">
                    
                    <input  type="checkbox" id="envio" className="form-check-input" checked={envio} onChange={onChange} />
                    <label htmlFor="envio">envio</label>
                </div>
                
                {/*-----Send Button-----*/}

                <button disabled={formInvalid || subiendoFoto} className={`btn btn-${editarId?'warning' : 'success'} mt-3 mb-5`}>{ subiendoFoto ? 'Subiendo imagen...' : editarId? 'Actualizar' : 'Enviar'}</button>

            </form>
        </div>

    )
    
}
