
import { useEffect, useState } from 'react';
import { Tabla } from './Tabla';
import { actualizarProducto, borrarProducto,  guardarProducto, obtenerProductos } from '../../Servicios/ServiciosProductos';
import { subirImagen } from '../../Servicios/upload';
import Ingreso from './Ingreso';

import Button from 'react-bootstrap/Button';
import Modal from 'react-bootstrap/Modal';

export function Index( props ){

    /*---------------------------*/
    /*----------Effects----------*/
    /*---------------------------*/

    useEffect(()=>{
        
        async function pedir(){
            const productos = await obtenerProductos();
            setProductos(productos)
        }
        pedir()
    },[])
    
    /*--------------------------*/
    /*----------States----------*/
    /*--------------------------*/

    const [ productos, setProductos ] = useState([]);
    const [producto, setProducto] = useState({
        nombre: '',
        precio: '',
        stock: '',
        marca: '',
        categoria: '', 
        detalles: '',
        foto: '',
        envio: '',
    });
    const [editarId, setEditarId] = useState(null); 
    const [archivoPendiente, setArchivoPendiente] = useState(null);
    const [subiendoFoto, setSubiendoFoto] = useState(false);

    
    /*-------------------------------------------------------------------------*/
    /*------Control del menu modal de confirmacion borrado del producto--------*/
    /*-------------------------------------------------------------------------*/

    const [show, setShow] = useState(false);
    const [borrarID, setBorrarID] = useState(null);

    const handleClose = () => setShow(false);
    const handleShow = () => setShow(true);

    /*-----------------------------*/
    /*----------functions----------*/
    /*-----------------------------*/

    function onChange(e) {
        const { type, id, value, checked } = e.target
        setProducto({...producto, [id]: type === 'checkbox'? checked : value})
    }

    /*-------------------------------------------*/
    /*------Incorporación / actualización--------*/
    /*-------------------------------------------*/

    async function onSubmit(e){
        e.preventDefault();
         
        const productosClon = [...productos];

        try {
            let productoParaGuardar = { ...producto };

            if (archivoPendiente) {
                const data = new FormData();
                data.append('archivo', archivoPendiente);
                setSubiendoFoto(true);

                const urlFotoSubida = await subirImagen(data);
                productoParaGuardar.foto = urlFotoSubida;
            }

            if(!editarId){
                
                /*Guardo de forma remota*/

                const productoGuardado = await guardarProducto(productoParaGuardar);

                /*Guardo producto formal local*/

                productosClon.push(productoGuardado);

            }else{

                const id = editarId;
                const productoActualizado = await actualizarProducto(id, productoParaGuardar);

                if (productoActualizado) {
                    const index = productosClon.findIndex( p => p.id === productoActualizado.id );

                    if (index !== -1) {
                        productosClon.splice(index, 1, productoActualizado);
                    }
                }

                setEditarId(null)
            }
            setProductos(productosClon);
            
            deleteForm();
        } catch (error) {
            console.log('ERROR SUBMIT PRODUCTO: ', error.message);
        } finally {
            setSubiendoFoto(false);
        }
    }

    /*-----------------*/
    /*--Resetear Form--*/
    /*-----------------*/

    function deleteForm(){
        setProducto({
            nombre: '',
            precio: '',
            stock: '',
            marca: '',
            categoria: '', 
            detalles: '',
            foto: '',
            envio: '',
        })
        setArchivoPendiente(null);
    }

    function formInvalid(){

        const p = producto;

        const noValido = !/^[a-zA-Z0-9Ã¡Ã©Ã­Ã³ÃºÃÃ‰ÃÃ“ÃšÃ±Ã‘\s\-()."]{2,100}$/.test(p.nombre.trim())||
                         !/^(?:[1-9]\d*(?:\.\d{1,2})?|0\.(?:0[1-9]|[1-9]\d?))$/.test(p.precio)||
                         !/^(0|[1-9]\d*)$/.test(p.stock)     ||
                         !p.marca     ||
                         !p.categoria ||
                         !p.detalles  ||
                         (!p.foto && !archivoPendiente)
        return noValido
    }

    /*------------------*/
    /*--Boton eliminar--*/
    /*------------------*/

    function deleteButton(id){
       
        if(id){
            setBorrarID(id)
            handleShow()
        }
    }
    async function goBorrar() {
        
        const id = borrarID;
        
        if(id){
        
            const productoEliminado = await borrarProducto(id);

            const productoClon = [...productos];
            const index = productoClon.findIndex( p => p.id === productoEliminado.id );
            productoClon.splice( index, 1 );
            setProductos( productoClon );   
        }                 
        handleClose();                                     
    }

    /*----------------*/
    /*--Boton Editar--*/
    /*----------------*/

    function editButton (id){
        if(!editarId ){
            setEditarId(id);
            setArchivoPendiente(null);
            setProducto({ ...productos.find( p => p.id === id ) });
        }
        else{
            setEditarId(null);
            deleteForm();
        }
    }

    function enviarArchivoFoto(archivo){
        setArchivoPendiente(archivo);
    }

    function borrarArchivoFoto(){
        setArchivoPendiente(null);
        setProducto({...producto, foto: ''});
    }

    return(
        <div className="Alta">
            <div className="jumbotron">

                <Modal show={show} onHide={handleClose}>
                    <Modal.Header closeButton>
                        <Modal.Title>Borrado de Producto</Modal.Title>
                    </Modal.Header>

                    <Modal.Body>
                        ¿Desea eliminar el producto de nombre {productos.find(p => p.id === borrarID)?.nombre}?
                    </Modal.Body>
                    
                    <Modal.Footer>
                        <Button variant="secondary" onClick={handleClose}>Cancelar</Button>
                        <Button variant="danger" onClick={goBorrar}>Aceptar</Button>
                    </Modal.Footer>
                </Modal>

                <Ingreso producto={producto}
                         onChange={onChange}
                         onSubmit={onSubmit}
                         editarId={editarId}
                         formInvalid={formInvalid()}
                         enviarArchivoFoto={enviarArchivoFoto}
                         borrarArchivoFoto={borrarArchivoFoto}
                         archivoPendiente={archivoPendiente}
                         subiendoFoto={subiendoFoto}
                />

                <Tabla productos={productos} 
                       deleteButton={deleteButton}
                       editButton={editButton}
                       editarId={editarId}
                />

            </div>
        </div>

    )

}
