import './App.css';
 import { Index as Inicio } from './Componentes/INICIO/Index';
import {Index as NavBar} from './Componentes/NAVBAR/Index';
import {Index as Alta} from './Componentes/ALTA/Index';
import Carrito from './Componentes/CARRITO/Index';
import Contacto from './Componentes/CONTACTO/Index';
import Nosotros from './Componentes/NOSOTROS/Index';
import {Index as RutaNoValida} from './Componentes/RutaNoValida/index';

import { BrowserRouter, Route, Routes } from 'react-router-dom';
function App() {
  return (
    <div className="App">

        {/*control del router*/}
        <BrowserRouter>
                
          {/*Barra de navegación*/}
          <NavBar/>

          {/*Zona de definición de Rutas*/}
          
          <Routes>

            {/*Ruta Raiz*/}
            <Route index element = { <Inicio/> }/>

            {/*Componentes a rutear*/}
            <Route path="/" element = { <Inicio/> }/>
            <Route path="alta" element = { <Alta/> }/>
            <Route path="carrito" element = { <Carrito/> }/>
            <Route path="contacto" element = { <Contacto/> }/>
            <Route path="nosotros" element = { <Nosotros/> }/>

            {/*Rutas por defecto*/}
            <Route path="*" element = { <RutaNoValida/> }/>
            
          </Routes>

        </BrowserRouter>

    </div>
  );
}

export default App;
