import { useEffect, useState } from 'react';
import './ObtenerFoto.css'

export function ObtenerFoto(props) {

    const { foto, archivoPendiente, enviarArchivoFoto, borrarArchivoFoto, subiendo } = props;

    const [valorInput, setValorInput] = useState('');
    const [vistaPrevia, setVistaPrevia] = useState('');

    useEffect(() => {
        if (!archivoPendiente) {
            setVistaPrevia('');
            return;
        }

        const objectUrl = URL.createObjectURL(archivoPendiente);
        setVistaPrevia(objectUrl);

        return () => URL.revokeObjectURL(objectUrl);
    }, [archivoPendiente]);

    const dragenter = e => {
        e.preventDefault();
    }
    const dragover = e => {
        e.preventDefault();
    }
    const dragleave = e => {
        e.preventDefault();
    }
    const drop = e => {
        e.preventDefault();
        const archivo = e.dataTransfer.files[0];
        prepararFoto(archivo);
    }

    const change = e => {
        const archivo = e.target.files[0];
        prepararFoto(archivo);

        setValorInput('')
    }

    const borrarFoto = () => {
        setValorInput('');
        borrarArchivoFoto();
    }

    const prepararFoto = archivo => {
        if (!archivo) {
            return;
        }

        if (archivo.type.includes('image')) {
            enviarArchivoFoto(archivo);
        } else {
            console.log('El archivo no es una img');
        }

    }

    const urlMostrada = vistaPrevia || foto;

    return (

        <div className='ObtenerFoto'>

            <input id='archivo' type='file' accept='image/*' value={valorInput} onChange={change} />

            <div
                id='drop'
                className={urlMostrada ? 'con-foto' : ''}
                onDragOver={dragover}
                onDragEnter={dragenter}
                onDragLeave={dragleave}
                onDrop={drop}
            >
                {subiendo && (
                    <div className='overlay-carga'>
                        <div className='spinner-circular'></div>
                        <span>Subiendo imagen...</span>
                    </div>
                )}

                {!urlMostrada && (
                    <label htmlFor='archivo'>
                        {'D&D o CLICK'}
                    </label>
                )}

                {urlMostrada && (
                    <>
                        <img src={urlMostrada} alt='Vista previa de la foto seleccionada' />
                        <button type='button' className='borrar-foto' onClick={borrarFoto}>
                            Quitar foto
                        </button>
                    </>
                )}
            </div>

        </div>

    )

}
