import { useEffect, useState } from 'react'

import './Index.css'

import { obtenerProductos } from '../../Servicios/ServiciosProductos'
import { Card } from './Card'
import { useLocalStorage } from '../../HOOKS/useLocalStorage'

export function Index(props) {
    

    const [productos, setProductos] = useState([])
    const [carrito, setCarrito] = useLocalStorage('carrito', [])

    useEffect(() => {

        async function pedir() {
            const productos = await obtenerProductos()
            setProductos(productos)
        }
        pedir()

       
    }, [])


    function agregarCarritoID(id) {
     
        const carritoClon = [...carrito];
        const producto = productos.find(p => p.id === id);
        const carritoClonId = carritoClon.findIndex(p=>p.id===id)
        
        if(producto.stock > 0 && (!producto.cantidad || producto.cantidad < producto.stock)
            && (!carritoClon[carritoClonId] || carritoClon[carritoClonId]?.cantidad < producto.stock)) {

            let pC = carritoClon.find(prodC => prodC.id === producto.id); 
            if(!pC) {
                producto.cantidad = 1
                carritoClon.push(producto);
            }
            else {
                pC.cantidad++
            }
            setCarrito(carritoClon)
        }
    }
   
    return (
        <div className="Inicio">
            <div className="jumbotron">
                <h3>Componente Carrito</h3>
                <hr />

                <div className="inicio">
                    <div className="section-cards">
                        <div className="section-cards-header">
                            <h1>Listado de productos</h1>
                        </div>

                        <div className="cards-container">
                            { productos.map( (producto, index) => 
                                    <Card 
                                        key={index} 
                                        producto={producto} 
                                        agregarCarritoID={agregarCarritoID}
                                    />
                                )
                            }
                        </div>

                    </div>
                </div>
            </div>
        </div>
    )
}