import axios from "axios"
const URL_API_CARRITO = process.env.NODE_ENV === 'production' 
                        ? '/api/carrito/' 
                        : `http://localhost:${process.env.REACT_APP_PORT_SRV_DEV}/api/carrito/`;

export async function enviarCarrito( pedido ){
    
    try{
        
        const {data: saveData} = await axios.post(URL_API_CARRITO, pedido);
        return saveData;

    }catch(error){

        console.log("ERROR POST AXIOS: ", error.message);
        return [];

    }  
}

export async function getPreference(carrito){
    
    const requestBody = {
        items: carrito.map(producto =>({
        
        id: producto.id,
        title: producto.nombre,
        quantity: parseInt(producto.cantidad),
        unit_price: Number(producto.precio),
        currency_id: "ARS",
        picture_url: producto.imagen
           
    }))
    }

    console.log("requestBody: ", requestBody);
    return axios.post(URL_API_CARRITO + 'mp/create_preference', requestBody)
    
}